  const make = (tag, attributes = {}) => {
    const element = document.createElementNS('http://www.w3.org/2000/svg', tag);
    for (const [key, value] of Object.entries(attributes)) element.setAttribute(key, String(value));
    return element;
  };
  for (const host of document.querySelectorAll('[data-bot-avatar]')) {
    const name = host.dataset.botAvatar, animal = artwork[name];
    if (!animal) continue;
    host.classList.add('pixel-mascot', 'motion-' + animal.motion);
    if (name === 'docfoo') host.classList.add('docfoo-avatar');
    host.style.setProperty('--mascot-delay', animal.delay + 's');
    host.style.setProperty('--mascot-period', animal.period + 's');
    const extent = animal.grid + 2;
    const graphic = make('svg', { viewBox: '0 0 ' + extent + ' ' + extent, 'shape-rendering': 'crispEdges', 'aria-hidden': 'true', focusable: 'false' });
    const shadow = make('g', { class: 'mascot-shadow', fill: animal.ink, opacity: '.24' });
    shadow.append(make('rect', { x: name === 'docfoo' ? 9 : 7, y: animal.grid, width: name === 'docfoo' ? 16 : 12, height: 1 }));
    const figure = make('g', { class: 'mascot-character' });
    const pixels = make('g', { transform: 'translate(1 1)' });
    for (const layer of animal.layers) {
      const cls = layer.name.startsWith('eye-') ? 'mascot-eye ' + layer.name : 'mascot-' + layer.name;
      const part = make('g', { class: cls, 'data-part': layer.name });
      if (layer.transform) { part.setAttribute('transform', layer.transform); part.setAttribute('data-logo', 'genie'); }
      for (const attributes of layer.paths) part.append(make('path', attributes));
      pixels.append(part);
    }
    figure.append(pixels); graphic.append(shadow, figure);
    host.replaceChildren(graphic);
  }
